// Precondition: count is a non-negative integer
function itemCost(price, count) { return price * count; }
console.log(itemCost(5, 4));

function makeLabel(name) { return 'Item: ' + name; }
const label = makeLabel('Pen');
console.log(label.startsWith('Item: '));

// Input: minutes (number >= 0)
// Output: whole hours and leftover minutes
function splitTime(minutes) { return [Math.floor(minutes / 60), minutes % 60]; }
console.log(splitTime(135));
